+import { ServiceError } from './github.mjs';
+
+// Cache metadata briefly in the running service, never in Git or public files.
+// Read authorization is checked before every cache lookup, including anonymous requests.
+const caches = new WeakMap(), profileCaches = new WeakMap();
+const metadata = `id url createdAt updatedAt isMinimized author { login avatarUrl(size:96) url ... on User { name } }`;
+const pageInfo = 'pageInfo { hasNextPage endCursor }';
+const parents = `${pageInfo} nodes { ${metadata} replies { totalCount } }`;
+const replies = `${pageInfo} nodes { ${metadata} }`;
+const unavailable = () => new ServiceError(502, 'Comment counts are unavailable. Please try again.');
+const loginPattern = /^[A-Za-z0-9][A-Za-z0-9-]{0,38}$/;
+const profile = author => ({ githubLogin:author.login, name:author.name || author.login,
+  avatar:author.avatarUrl, profileUrl:author.url });
+
+async function nodes(github, ids, fields, token) {
+  const result = [];
+  for (let offset = 0; offset < ids.length; offset += 50) {
+    const data = await github.graphql(`query($ids:[ID!]!) { nodes(ids:$ids) { ${fields} } }`, { ids:ids.slice(offset, offset + 50) }, token);
+    if (!Array.isArray(data.nodes)) throw unavailable();
+    result.push(...data.nodes.filter(Boolean));
+  }
+  return result;
+}
+
+async function pages(first, next, visit) {
+  let page = first;
+  const cursors = new Set();
+  for (;;) {
+    if (!Array.isArray(page?.nodes) || !page.pageInfo) throw unavailable();
+    for (const item of page.nodes) if (item) visit(item);
+    if (!page.pageInfo.hasNextPage) return;
+    const cursor = page.pageInfo.endCursor;
+    if (!cursor || cursors.has(cursor)) throw unavailable();
+    cursors.add(cursor);
+    page = await next(cursor);
+  }
+}
+
+async function collect(github, entries, token) {
+  const byDiscussion = new Map(Object.entries(entries).map(([id, entry]) => [entry.nodeId, id]));
+  const comments = new Map(), replyParents = new Map();
+  function add(comment, instanceId, isReply) {
+    if (!comment.id || !comment.createdAt || !Number.isFinite(Date.parse(comment.createdAt))) throw unavailable();
+    // Deleted accounts have no attributable identity. Hidden posts are not promoted.
+    if (!comment.author || comment.isMinimized) return;
+    const number = /#discussioncomment-(\d+)$/.exec(comment.url || '')?.[1];
+    if (!number) throw unavailable();
+    comments.set(comment.id, { id:comment.id, number, instanceId, isReply,
+      createdAt:comment.createdAt, updatedAt:comment.updatedAt, author:profile(comment.author) });
+  }
+  const discussions = await nodes(github, [...byDiscussion.keys()], `... on Discussion { id comments(first:100) { ${parents} } }`, token);
+  for (const discussion of discussions) {
+    const instanceId = byDiscussion.get(discussion.id);
+    if (!instanceId) continue;
+    await pages(discussion.comments, async after => {
+      const data = await github.graphql(`query($id:ID!,$after:String!) { node(id:$id) { ... on Discussion { id comments(first:100,after:$after) { ${parents} } } } }`, { id:discussion.id, after }, token);
+      if (data.node?.id !== discussion.id) throw unavailable();
+      return data.node.comments;
+    }, comment => {
+      add(comment, instanceId, false);
+      const count = comment.replies?.totalCount;
+      if (!Number.isSafeInteger(count) || count < 0) throw unavailable();
+      if (count) replyParents.set(comment.id, instanceId);
+    });
+  }
+  const threads = await nodes(github, [...replyParents.keys()], `... on DiscussionComment { id replies(first:100) { ${replies} } }`, token);
+  for (const thread of threads) {
+    const instanceId = replyParents.get(thread.id);
+    if (!instanceId) continue;
+    await pages(thread.replies, async after => {
+      const data = await github.graphql(`query($id:ID!,$after:String!) { node(id:$id) { ... on DiscussionComment { id replies(first:100,after:$after) { ${replies} } } } }`, { id:thread.id, after }, token);
+      if (data.node?.id !== thread.id) throw unavailable();
+      return data.node.replies;
+    }, reply => add(reply, instanceId, true));
+  }
+  return [...comments.values()];
+}
+
+async function index(github, entries, session) {
+  const token = await github.readToken(session), key = JSON.stringify(entries);
+  let cache = caches.get(github);
+  if (cache?.token !== token || cache.key !== key || cache.expires <= Date.now()) {
+    cache = { token, key, expires:Date.now() + 15000, pending:collect(github, entries, token) };
+    caches.set(github, cache);
+  }
+  try { return { token, comments:await cache.pending }; }
+  catch (error) { if (caches.get(github) === cache) caches.delete(github); throw error; }
+}
+
+export function invalidateCommentLeaderboard(github) { caches.delete(github); }
+
+export async function readCommentLeaderboard(github, entries, session) {
+  const { comments } = await index(github, entries, session), accounts = new Map();
+  for (const comment of comments) {
+    const key = comment.author.githubLogin.toLowerCase();
+    const row = accounts.get(key) || { ...comment.author, score:0, reachedCountAt:comment.createdAt };
+    row.score++;
+    if (comment.createdAt > row.reachedCountAt) row.reachedCountAt = comment.createdAt;
+    accounts.set(key, row);
+  }
+  const rows = [...accounts.values()].sort((a, b) => b.score - a.score ||
+    Date.parse(a.reachedCountAt) - Date.parse(b.reachedCountAt) || a.githubLogin.toLowerCase().localeCompare(b.githubLogin.toLowerCase()));
+  return { rows:rows.map((row, i) => ({ ...row, rank:i + 1 })) };
+}
+
+export async function readContributorComments(github, entries, login, session) {
+  if (!loginPattern.test(login)) throw new ServiceError(400, 'Invalid GitHub username.');
+  const { token, comments } = await index(github, entries, session);
+  const selected = comments.filter(c => c.author.githubLogin.toLowerCase() === login.toLowerCase());
+  const byId = new Map(selected.map(c => [c.id, c]));
+  // Bodies are read fresh, only for the selected contributor. No body cache.
+  const fresh = await nodes(github, selected.map(c => c.id), `... on DiscussionComment { ${metadata} body discussion { id } }`, token);
+  const result = [];
+  for (const comment of fresh) {
+    const saved = byId.get(comment.id);
+    if (!saved || comment.isMinimized || comment.author?.login.toLowerCase() !== login.toLowerCase() ||
+        comment.discussion?.id !== entries[saved.instanceId]?.nodeId) continue;
+    result.push({ instanceId:saved.instanceId, number:saved.number, isReply:saved.isReply,
+      createdAt:comment.createdAt, updatedAt:comment.updatedAt, body:comment.body });
+  }
+  if (result.length !== selected.length) invalidateCommentLeaderboard(github);
+  result.sort((a, b) => Date.parse(b.createdAt) - Date.parse(a.createdAt) || b.number.localeCompare(a.number));
+  return { comments:result };
+}
+
+export async function readProfiles(github, logins, session) {
+  if (!logins.length || logins.length > 50 || logins.some(login => !loginPattern.test(login))) throw new ServiceError(400, 'Invalid GitHub usernames.');
+  const token = await github.readToken(session), key = [...new Set(logins)].sort().join(',');
+  const cached = profileCaches.get(github);
+  if (cached?.token === token && cached.key === key && cached.expires > Date.now()) return cached.value;
+  // REST returns null for deleted users without making the entire batch fail.
+  const accounts = await Promise.all([...new Set(logins)].map(async login => {
+    try {
+      const user = await github.call(`/users/${encodeURIComponent(login)}`, { token });
+      return { githubLogin:user.login, name:user.name || user.login, avatar:user.avatar_url, profileUrl:user.html_url };
+    } catch (error) { if (error.status !== 403) throw error; return { githubLogin:login, name:login }; }
+  }));
+  const value = { accounts };
+  profileCaches.set(github, { token, key, value, expires:Date.now() + 300000 });
+  return value;
+}

